# @param badge [Gamification::Badge]
def initialize(badge)
  @badge = badge
end

def gained?
  @badge.persisted?
}

def level_title
  lookup = [
    :"gamification.badge.level.#{@badge.name.downcase}.#{@badge.level}",
    :"gamification.badge.level.default.#{@badge.level}",
    @badge.level,
  ]

  I18n.t(lookup.shift, default: lookup)
}

class << self
  def notification(name, opts = {})
    notifications[name] = opts
  end

  def notifications
    @notifications ||= {}
  end
end
